
.mission-card {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  width: 100%;
  padding: 0.85rem 0.9rem;
  border-radius: 0.9rem;
  border: 2px solid var(--farm-wood);
  background: var(--farm-cream);
  text-align: left;
}

.mission-card--completed {
  border-color: var(--farm-accent-dark);
  background: var(--farm-cream-dark);
}

.mission-card__icon {
  font-size: 1.75rem;
  line-height: 1;
  flex-shrink: 0;
}

.mission-card__body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.mission-card__title {
  font-size: 0.92rem;
  font-weight: 800;
  color: var(--farm-text-dark);
}

.mission-card__desc {
  font-size: 0.75rem;
  color: var(--farm-text-muted);
}

.mission-card__points {
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--farm-accent-dark);
}

.mission-card__chevron {
  width: 1.4rem;
  height: 1.4rem;
  color: var(--farm-text-muted);
  flex-shrink: 0;
}

.mission-card__chevron--done {
  color: var(--farm-accent-dark);
}
